#include <bits/stdc++.h>
using namespace std;

class Solution {
    static const int MOD = 1000000007;
    vector<vector<int>> memo;
    int dfs(int u, int fuel, const vector<int>& a, int finish) {
        int& ans = memo[u][fuel];
        if (ans != -1) return ans;
        long long ways = (u == finish);
        for (int v = 0; v < (int)a.size(); ++v) {
            int cost = abs(a[u] - a[v]);
            if (u != v && cost <= fuel)
                ways += dfs(v, fuel - cost, a, finish);
        }
        return ans = ways % MOD;
    }
public:
    int countRoutes(vector<int>& locations, int start, int finish, int fuel) {
        memo.assign(locations.size(), vector<int>(fuel + 1, -1));
        return dfs(start, fuel, locations, finish);
    }
};
